def _band_cost(residual):
    e = np.abs(residual)
    skip = e > 3.0
    if np.any(skip):
        period = np.clip(np.median(e[skip]), 4.5, 7.5)
        e[skip] -= period
    return np.minimum(e ** 2, 0.35 ** 2).sum() + 0.02 * skip.sum()

def _cycle_cost(rays, p, residual, shape):
    absolute = np.abs(residual)
    skip = absolute > 3.0
    error = absolute.copy()
    if np.any(skip):
        period = np.clip(np.median(absolute[skip]), 4.5, 7.5)
        error[skip] -= period
    clock_excess = np.maximum(np.abs(rays.clocks @ p[5:]) - 4.0, 0.0)
    return np.minimum(error ** 2, 0.35 ** 2).sum() + 0.005 * skip.sum() + shape[0] * (clock_excess @ clock_excess)
